workers = list(set(r[1] for r in rows_data))
# If Dune is unavailable, workers excluding Dune:
avail_workers = [w for w in workers if w != 'Dune']
cost_map = {(r[0], r[1]): r[2] for r in rows_data}
min_cost = float('inf')
for p in permutations(avail_workers, len(tasks)):
    valid = True
    total = 0
    for t, w in zip(tasks, p):
        if (t, w) in cost_map:
            total += cost_map[(t, w)]
        else:
            valid = False
            break
    if valid and total < min_cost:
        min_cost = total
result = int(min_cost)

