rows = range(390, 399)
states = ['Idle', 'Active', 'Done']
prob = {}
for r in rows:
    f = cell(sheet, f'H{r}')
    t = cell(sheet, f'I{r}')
    p = num(sheet, f'G{r}')
    prob[(f, t)] = p

# States: Idle, Active, Done
# Initial state at step 0: Idle -> [1.0, 0.0, 0.0]
dist = {'Idle': 1.0, 'Active': 0.0, 'Done': 0.0}

for step in range(4):
    new_dist = {'Idle': 0.0, 'Active': 0.0, 'Done': 0.0}
    for s in states:
        for t in states:
            p = prob.get((s, t), 0.0)
            new_dist[t] += dist[s] * p
    dist = new_dist

result = round(dist['Done'], 6)

sheet = 'Transition probabilities'
data = cells(sheet, 'G390:I398')
trans = {}
for row in data:
    prob, frm, to = row
    trans[(frm, to)] = prob
states = ['Active', 'Idle', 'Done']
v = {'Active': 0.0, 'Idle': 1.0, 'Done': 0.0}
for step in range(4):
    new_v = {}
    for s in states:
        new_v[s] = sum(v[frm] * trans.get((frm, s), 0.0) for frm in states)
    v = new_v
result = round(v['Done'], 6)

